-- c011-v001: Digo pois, por–acaso rejeitou – Deus o– povo dele? De–modo–nenhum seja! Também pois eu israelita sou, da– semente de–Abraão, da–tribo de–Benjamim.
-- c011-v002: Não rejeitou – Deus, o– povo dele, o–qual de–antemão–conheceu. Ou não sabeis em– Elias que diz a– Escritura? Como intercede a– Deus contra– – Israel,
-- c011-v003: Senhor, os– profetas teus mataram; os– altares teus derrubaram; e–eu fui–deixado sozinho, e buscam a– vida minha.
-- c011-v004: Mas que diz a–ele a– resposta–divina? Reservei para–mim–mesmo sete–mil homens, os–quais não dobraram joelho a– Baal.
-- c011-v005: Assim pois também, no– – presente tempo, remanescente segundo– eleição de–graça tem–havido.
-- c011-v006: Se porém por–graça, já–não por– obras; visto–que a– graça já–não seria graça; <Se porém por– obras, já–não é graça; visto–que a– obra já–não é obra>.
-- c011-v007: Que pois? Que busca Israel, isto não alcançou; a– porém eleição alcançou; os– porém restantes foram–endurecidos,
-- c011-v008: como está–escrito, Deu– lhes – Deus espírito de–torpor, olhos para– não ver, e ouvidos para– não ouvir, até– o– hoje dia.
-- c011-v009: E Davi diz, Torne–se a– mesa deles, em– laço, e em– armadilha, e em– tropeço, e em– retribuição para–eles;
-- c011-v010: obscureçam–se os– olhos deles, para– não ver, e o– dorso deles, para– sempre curva.
-- c011-v011: Digo pois, por–acaso tropeçaram para–que caíssem? De–modo–nenhum seja! Mas pela– deles transgressão, a– salvação para–os– gentios, para– o– provocar–ao–ciúme– os.
-- c011-v012: Se porém, a– transgressão deles, riqueza do–mundo, e a– diminuição deles, riqueza de–gentios, quanto mais a– plenitude deles?
-- c011-v013: A–vós porém digo, os– gentios, na–medida–em– que de–fato pois sou eu de–gentios apóstolo, o– ministério meu glorifico,
-- c011-v014: se de–algum–modo provocar–ao–ciúme minha a– carne, e salvar alguns de– eles.
-- c011-v015: Se pois a– rejeição deles reconciliação do–mundo, que a– recepção, senão – vida dentre– mortos?
-- c011-v016: Se porém as– primícias santas, também a– massa; e se a– raiz santa, também os– ramos.
-- c011-v017: Se porém alguns dos– ramos foram–cortados, tu porém, oliveira–brava sendo, foste–enxertado entre– eles, e co–participante da– raiz da– riqueza da– oliveira tornaste–te,
-- c011-v018: não te–glories–contra os– ramos. Se porém te–glorias–contra, não tu a– raiz sustentas, mas a– raiz a–ti.
-- c011-v019: Dirás pois, Foram–cortados ramos, para–que eu fosse–enxertado.
-- c011-v020: Bem; pela– incredulidade foram–cortados, tu porém pela– fé estás–firme. Não altivamente penses, mas teme.
-- c011-v021: Se pois – Deus os– segundo– natureza ramos, não poupou, [de–modo–nenhum] [também] nem a–ti poupará.
-- c011-v022: Vê pois bondade e severidade de–Deus: sobre– de–fato os– que–caíram, severidade; sobre– porém ti, bondade de–Deus, se permaneceres na– bondade, visto–que também tu serás–cortado.
-- c011-v023: E–aqueles porém se não permanecerem na– incredulidade, serão–enxertados; poderoso pois é – Deus novamente enxertar– os.
-- c011-v024: Se pois tu, da– – segundo– natureza foste–cortado oliveira–brava, e, contra– natureza, foste–enxertado em– boa–oliveira, quanto mais estes, os– segundo– natureza, serão–enxertados na– própria oliveira?
-- c011-v025: Não pois quero vós ignorar, irmãos, o– mistério este, para–que não sejais em– vós–mesmos sábios: que endurecimento em– parte a– Israel aconteceu, até– que a– plenitude dos– gentios entre;
-- c011-v026: e assim todo Israel será–salvo, como está–escrito, Virá de– Sião o– Libertador, afastará impiedades de– Jacó.
-- c011-v027: E esta a–eles, a– da–minha–parte – aliança, quando tirar os– pecados deles.
-- c011-v028: Segundo– de–fato o– evangelho, inimigos por–causa–de– vós; segundo– porém a– eleição, amados por–causa–dos– – pais.
-- c011-v029: Irrevogáveis pois os– dons e a– vocação – de–Deus.
-- c011-v030: Assim–como pois vós outrora desobedecestes a– Deus, agora porém alcançastes–misericórdia, pela– destes desobediência;
-- c011-v031: assim também estes agora desobedeceram, pela– vossa misericórdia, para–que também eles agora, alcancem–misericórdia.
-- c011-v032: Encerrou pois, – Deus a– todos em– desobediência, para–que a– todos tenha–misericórdia.
-- c011-v033: Ó, profundidade de–riqueza, e de–sabedoria, e de–conhecimento de–Deus! Quão inescrutaveis os– juízos dele, e insondáveis os– caminhos dele!
-- c011-v034: Quem pois conheceu mente do–Senhor, ou quem conselheiro dele tornou–se?
-- c011-v035: Ou quem primeiro–deu a–ele, e será–retribuído a–ele?
-- c011-v036: Porque dele, – e por– ele, e para– ele, todas–as– coisas. A–ele a– glória para– os– séculos! Amém.

